package io.github.eslamasabry.oc.feature.settings.presentation

/** One handled error as `:engine:diagnostics` keeps it: [message] is already redacted there (B-SEC-008). */
public data class ReportError(val at: String, val source: String, val message: String, val occurrences: Int = 1)

/**
 * What the report says. Every field is generated by the app (versions, counts, choice names); nothing typed by the
 * person or sent by a server, no server address, name or credential (B-SEC-041).
 */
public data class ReportFacts(
    val appVersion: String,
    val build: String,
    /** "Android 15 (API 35)". */
    val platform: String,
    val language: String,
    val textSize: String,
    val motion: String,
    val savedServers: Int,
    val connectedServers: Int,
    /** Oldest first, as the diagnostics ring keeps them. */
    val errors: List<ReportError> = emptyList(),
)

/** The report text (Flutter Report a problem's diagnostics block): fixed English labels, since it is read by maintainers. */
public object DiagnosticsReport {
    /** At most this many errors, newest first; the ring keeps more but a report stays readable. */
    public const val MAX_ERRORS: Int = 20

    /** One error line is cut here, so one runaway message cannot crowd out the rest. */
    public const val MAX_LINE: Int = 300

    public fun text(f: ReportFacts): String = buildString {
        appendLine("OpenCode Mobile ${f.appVersion}+${f.build}")
        appendLine(f.platform)
        appendLine("Language: ${f.language} · Text size: ${f.textSize} · Motion: ${f.motion}")
        appendLine("Servers: ${f.savedServers} saved · ${f.connectedServers} connected")
        if (f.errors.isEmpty()) {
            append("No errors kept on this phone.")
        } else {
            appendLine("Errors kept on this phone: ${f.errors.size}")
            val shown = f.errors.asReversed().take(MAX_ERRORS)
            shown.forEachIndexed { i, e ->
                val repeats = if (e.occurrences > 1) " ×${e.occurrences}" else ""
                val line = "${e.at} ${e.source}$repeats: ${e.message.lineSequence().firstOrNull().orEmpty()}"
                append("- ").append(if (line.length > MAX_LINE) line.take(MAX_LINE - 1) + "…" else line)
                if (i < shown.lastIndex) appendLine()
            }
            if (f.errors.size > shown.size) {
                appendLine()
                append("(${f.errors.size - shown.size} older not shown)")
            }
        }
    }
}
